import React, { useContext, useState } from "react";
import noteContext from "../context/notes/noteContext";

const AddNote = (props) => {
  const context = useContext(noteContext);
  const { addNote } = context;
  const [note, setNote] = useState({ 
    title: "", 
    description: "", 
    tag: ""
  });
  const [isExpanded, setIsExpanded] = useState(false);

  const handleClick = async (e) => {
    e.preventDefault();

    try {
      const success = await addNote(note.title, note.description, note.tag);
      
      if (success !== false) {
        setNote({ title: "", description: "", tag: "" });
        setIsExpanded(false);
        props.showAlert("Note created successfully! 📝", "success");
      } else {
        props.showAlert("Failed to create note. Please try again.", "danger");
      }
    } catch (error) {
      console.error('Error in handleClick:', error);
      props.showAlert("Failed to create note. Please try again.", "danger");
    }
  };

  const onChange = (e) => {
    setNote({ ...note, [e.target.name]: e.target.value });
    if (!isExpanded && (e.target.name === 'title' || e.target.name === 'description')) {
      setIsExpanded(true);
    }
  };

  const handleCancel = () => {
    setNote({ title: "", description: "", tag: "" });
    setIsExpanded(false);
  };

  const characterCount = note.description.length;
  const isFormValid = note.title.length >= 5 && note.description.length >= 5;

  return (
    <div className="add-note-container">
      <div className="card add-note-card">
        <div className="card-header">
          <div className="add-note-header">
            <div className="add-note-icon">
              <i className="fas fa-plus"></i>
            </div>
            <div>
              <h2 className="mb-1">Create New Note</h2>
              <p className="text-muted mb-0">Capture your thoughts and ideas</p>
            </div>
          </div>
        </div>
        
        <div className="card-body">
          <form onSubmit={handleClick} className="add-note-form">
            {/* Title Input - Always Visible */}
            <div className="form-group">
              <label htmlFor="title" className="form-label">
                <i className="fas fa-heading me-2"></i>Title
              </label>
              <input
                type="text"
                className="form-control title-input"
                id="title"
                name="title"
                onChange={onChange}
                value={note.title}
                placeholder="What's on your mind?"
                required
                autoComplete="off"
              />
              <div className="form-text">
                {note.title.length}/∞ characters {note.title.length >= 5 ? '✓' : '(minimum 5)'}
              </div>
            </div>

            {/* Expandable Section */}
            <div className={`expandable-section ${isExpanded ? 'expanded' : ''}`}>
              <div className="form-group">
                <label htmlFor="description" className="form-label">
                  <i className="fas fa-align-left me-2"></i>Content
                </label>
                <textarea
                  className="form-control content-textarea"
                  id="description"
                  name="description"
                  onChange={onChange}
                  rows={isExpanded ? "8" : "4"}
                  value={note.description}
                  placeholder="Start writing your note here... Share your thoughts, ideas, or anything that comes to mind."
                  required
                />
                <div className="form-text">
                  <div className="character-count">
                    <span className={characterCount >= 5 ? 'valid' : 'invalid'}>
                      {characterCount} characters {characterCount >= 5 ? '✓' : '(minimum 5)'}
                    </span>
                  </div>
                </div>
              </div>

              <div className="form-group">
                <label htmlFor="tag" className="form-label">
                  <i className="fas fa-tag me-2"></i>Tag (Optional)
                </label>
                <input
                  type="text"
                  className="form-control"
                  id="tag"
                  name="tag"
                  value={note.tag}
                  onChange={onChange}
                  placeholder="Add a tag to organize your note"
                  autoComplete="off"
                />
                <div className="form-text">
                  Help categorize your note for easy searching
                </div>
              </div>

              {/* Action Buttons */}
              <div className="form-actions">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={handleCancel}
                >
                  <i className="fas fa-times me-2"></i>Cancel
                </button>
                <button
                  type="submit"
                  className="btn btn-primary"
                  disabled={!isFormValid}
                >
                  <i className="fas fa-save me-2"></i>Save Note
                </button>
              </div>
            </div>

            {/* Quick Action Button - Only show when not expanded */}
            {!isExpanded && (
              <div className="quick-expand">
                <button
                  type="button"
                  className="btn btn-outline-primary btn-sm"
                  onClick={() => setIsExpanded(true)}
                >
                  <i className="fas fa-expand-alt me-2"></i>Add More Details
                </button>
              </div>
            )}
          </form>
        </div>
      </div>

      {/* Quick Tips */}
      {isExpanded && (
        <div className="quick-tips fade-in">
          <div className="tips-header">
            <i className="fas fa-lightbulb"></i>
            <span>Quick Tips</span>
          </div>
          <div className="tips-list">
            <div className="tip-item">
              <i className="fas fa-check"></i>
              <span>Use descriptive titles for easy searching</span>
            </div>
            <div className="tip-item">
              <i className="fas fa-check"></i>
              <span>Tags help organize notes by topic or project</span>
            </div>
            <div className="tip-item">
              <i className="fas fa-check"></i>
              <span>Your notes are automatically saved in the cloud</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AddNote;
